// ANTI-PATTERN en Power Query (M): Fechas repetidas + / 31.0 fijo + Table.SelectRows por fila (rompe Query Folding)
= Table.AddColumn(Saldos, "TasaLOCF", each
    List.First(Table.Sort(Table.SelectRows(Tasas, (t) => t[fecha_tasa] <= #date(2025,12,31)), {{"fecha_tasa", Order.Descending}})[tasa_eur_usd]) / 31.0
)

