// OPTIMIZADO en Power Query (M): Parámetro único dinámico + Query Folding preservado
let
    FechaBase = #date(2025, 12, 1),
    IniMes = Date.StartOfMonth(FechaBase),
    FinMes = Date.EndOfMonth(FechaBase),
    DiasMes = Number.From(Date.DaysInMonth(FechaBase)),
    RangoSargable = Table.SelectRows(Saldos, each [fecha_foto] >= IniMes and [fecha_foto] <= FinMes
        and not Text.Contains([desc_producto], "TRANSITORIA") and not Text.Contains([desc_producto], "GARANTIA")),
    PreAgregado = Table.Group(RangoSargable, {"id_cliente", "moneda"}, {
        {"SaldoPromedioMes", each List.Sum([monto_original]) / DiasMes, type number}
    })
in
    PreAgregado
